import { AwsProvider } from "@cdktn/provider-aws/lib/provider";
import { AzurermProvider } from "@cdktn/provider-azurerm/lib/provider";
import { GoogleProvider } from "@cdktn/provider-google/lib/provider";
import { NullProvider } from "@cdktn/provider-null/lib/provider";
import { Construct } from "constructs";
// Generated by `cdktn get` (cdktf.json terraformProviders); not in Git
import { AzuredevopsProvider } from "../.gen/providers/azuredevops/provider";
import { REGION as AWS_REGION } from "../config/aws/common";
import { azureDevOpsConfig } from "../config/azure/cicd";
import { accounts } from "../config/commonsettings";
import { currentEnv } from "../config/environment";
import { isCloudEnabled } from "../config/features";
import {
  LOCATION as GOOGLE_REGION,
  PROJECT_NAME as GOOGLE_PROJECT,
} from "../config/google/common";

/**
 * The single place where Terraform providers are declared. Every module
 * receives providers from here (via `Providers` / `CloudContext`) and must not
 * instantiate providers itself.
 */
export interface Providers {
  aws: AwsProvider;
  google: GoogleProvider;
  azure: AzurermProvider;
  /**
   * Returns the (single, non-aliased) null provider, creating it on first
   * use so that only stacks with null resources declare it. Declaring it
   * also pins the provider version in `required_providers`.
   */
  null(): NullProvider;
  /**
   * Returns the Azure DevOps provider (organization of
   * config/azure/cicd.ts), creating it on first use. It signs in with the
   * service principal of ARM_CLIENT_ID / ARM_CLIENT_SECRET / ARM_TENANT_ID,
   * which must be a member of the organization.
   */
  azuredevops(): AzuredevopsProvider;
}

export const createProviders = (scope: Construct): Providers => {
  // Accounts of the environment (FEAT-04): when set, the providers refuse to
  // run against another account.
  const awsProvider = new AwsProvider(scope, "aws", {
    region: AWS_REGION,
    allowedAccountIds: accounts.awsAccountId
      ? [accounts.awsAccountId]
      : undefined,
  });

  if (isCloudEnabled("google") && !GOOGLE_PROJECT) {
    throw new Error(
      `PROJECT_NAME in config/google/common.ts is not set for DEPLOY_ENV "${currentEnv()}".`,
    );
  }
  const googleProvider = new GoogleProvider(scope, "google", {
    project: GOOGLE_PROJECT,
    region: GOOGLE_REGION,
  });

  const azureProvider = new AzurermProvider(scope, "azure", {
    subscriptionId: accounts.azureSubscriptionId,
    features: [{}],
  });

  let nullProvider: NullProvider | undefined;
  let azuredevopsProvider: AzuredevopsProvider | undefined;

  return {
    aws: awsProvider,
    google: googleProvider,
    azure: azureProvider,
    null: () => {
      nullProvider ??= new NullProvider(scope, "null");
      return nullProvider;
    },
    azuredevops: () => {
      azuredevopsProvider ??= new AzuredevopsProvider(scope, "azuredevops", {
        orgServiceUrl: `https://dev.azure.com/${azureDevOpsConfig.organization}`,
      });
      return azuredevopsProvider;
    },
  };
};
